package main

import (
	"encoding/json"
	"os"
	"sync/atomic"
	"syscall"

	"github.com/hanwen/go-fuse/v2/fuse"
)

// countFS wraps a RawFileSystem and counts the operations that reach the
// daemon (everything the kernel did not answer from its caches or via
// passthrough). Generated by hand from fuse.RawFileSystem.
type countFS struct {
	fuse.RawFileSystem
	ops   [33]atomic.Int64
	rdB   atomic.Int64
	wrB   atomic.Int64
	blobs *blobTiers

	// noFlush / noXattr answer ENOSYS without asking the node FS; the
	// kernel then stops sending FLUSH / *XATTR for the rest of the mount.
	noFlush, noXattr bool
}

var opNames = []string{"lookup", "getattr", "setattr", "mknod", "mkdir", "unlink", "rmdir", "rename", "link", "symlink", "readlink", "getxattr", "listxattr", "setxattr", "create", "open", "flush", "fsync", "opendir", "readdir", "readdirplus", "statfs", "access", "lseek", "copyfilerange", "fallocate", "statx", "read", "write", "release", "releasedir", "forget", "writev"}

func (c *countFS) Lookup(x <-chan struct{}, h *fuse.InHeader, n string, o *fuse.EntryOut) fuse.Status {
	c.ops[0].Add(1)
	return c.RawFileSystem.Lookup(x, h, n, o)
}
func (c *countFS) GetAttr(x <-chan struct{}, i *fuse.GetAttrIn, o *fuse.AttrOut) fuse.Status {
	c.ops[1].Add(1)
	return c.RawFileSystem.GetAttr(x, i, o)
}
func (c *countFS) SetAttr(x <-chan struct{}, i *fuse.SetAttrIn, o *fuse.AttrOut) fuse.Status {
	c.ops[2].Add(1)
	return c.RawFileSystem.SetAttr(x, i, o)
}
func (c *countFS) Mknod(x <-chan struct{}, i *fuse.MknodIn, n string, o *fuse.EntryOut) fuse.Status {
	c.ops[3].Add(1)
	return c.RawFileSystem.Mknod(x, i, n, o)
}
func (c *countFS) Mkdir(x <-chan struct{}, i *fuse.MkdirIn, n string, o *fuse.EntryOut) fuse.Status {
	c.ops[4].Add(1)
	return c.RawFileSystem.Mkdir(x, i, n, o)
}
func (c *countFS) Unlink(x <-chan struct{}, h *fuse.InHeader, n string) fuse.Status {
	c.ops[5].Add(1)
	return c.RawFileSystem.Unlink(x, h, n)
}
func (c *countFS) Rmdir(x <-chan struct{}, h *fuse.InHeader, n string) fuse.Status {
	c.ops[6].Add(1)
	return c.RawFileSystem.Rmdir(x, h, n)
}
func (c *countFS) Rename(x <-chan struct{}, i *fuse.RenameIn, a, b string) fuse.Status {
	c.ops[7].Add(1)
	return c.RawFileSystem.Rename(x, i, a, b)
}
func (c *countFS) Link(x <-chan struct{}, i *fuse.LinkIn, n string, o *fuse.EntryOut) fuse.Status {
	c.ops[8].Add(1)
	return c.RawFileSystem.Link(x, i, n, o)
}
func (c *countFS) Symlink(x <-chan struct{}, h *fuse.InHeader, t, n string, o *fuse.EntryOut) fuse.Status {
	c.ops[9].Add(1)
	return c.RawFileSystem.Symlink(x, h, t, n, o)
}
func (c *countFS) Readlink(x <-chan struct{}, h *fuse.InHeader) ([]byte, fuse.Status) {
	c.ops[10].Add(1)
	return c.RawFileSystem.Readlink(x, h)
}
func (c *countFS) GetXAttr(x <-chan struct{}, h *fuse.InHeader, a string, d []byte) (uint32, fuse.Status) {
	c.ops[11].Add(1)
	if c.noXattr {
		return 0, fuse.ENOSYS
	}
	return c.RawFileSystem.GetXAttr(x, h, a, d)
}
func (c *countFS) ListXAttr(x <-chan struct{}, h *fuse.InHeader, d []byte) (uint32, fuse.Status) {
	c.ops[12].Add(1)
	if c.noXattr {
		return 0, fuse.ENOSYS
	}
	return c.RawFileSystem.ListXAttr(x, h, d)
}
func (c *countFS) SetXAttr(x <-chan struct{}, i *fuse.SetXAttrIn, a string, d []byte) fuse.Status {
	c.ops[13].Add(1)
	return c.RawFileSystem.SetXAttr(x, i, a, d)
}
func (c *countFS) Create(x <-chan struct{}, i *fuse.CreateIn, n string, o *fuse.CreateOut) fuse.Status {
	c.ops[14].Add(1)
	return c.RawFileSystem.Create(x, i, n, o)
}
func (c *countFS) Open(x <-chan struct{}, i *fuse.OpenIn, o *fuse.OpenOut) fuse.Status {
	c.ops[15].Add(1)
	return c.RawFileSystem.Open(x, i, o)
}
func (c *countFS) Flush(x <-chan struct{}, i *fuse.FlushIn) fuse.Status {
	c.ops[16].Add(1)
	if c.noFlush {
		return fuse.ENOSYS
	}
	return c.RawFileSystem.Flush(x, i)
}
func (c *countFS) Fsync(x <-chan struct{}, i *fuse.FsyncIn) fuse.Status {
	c.ops[17].Add(1)
	return c.RawFileSystem.Fsync(x, i)
}
func (c *countFS) OpenDir(x <-chan struct{}, i *fuse.OpenIn, o *fuse.OpenOut) fuse.Status {
	c.ops[18].Add(1)
	return c.RawFileSystem.OpenDir(x, i, o)
}
func (c *countFS) ReadDir(x <-chan struct{}, i *fuse.ReadIn, o *fuse.DirEntryList) fuse.Status {
	c.ops[19].Add(1)
	return c.RawFileSystem.ReadDir(x, i, o)
}
func (c *countFS) ReadDirPlus(x <-chan struct{}, i *fuse.ReadIn, o *fuse.DirEntryList) fuse.Status {
	c.ops[20].Add(1)
	return c.RawFileSystem.ReadDirPlus(x, i, o)
}
func (c *countFS) StatFs(x <-chan struct{}, h *fuse.InHeader, o *fuse.StatfsOut) fuse.Status {
	c.ops[21].Add(1)
	return c.RawFileSystem.StatFs(x, h, o)
}
func (c *countFS) Access(x <-chan struct{}, i *fuse.AccessIn) fuse.Status {
	c.ops[22].Add(1)
	return c.RawFileSystem.Access(x, i)
}
func (c *countFS) Lseek(x <-chan struct{}, i *fuse.LseekIn, o *fuse.LseekOut) fuse.Status {
	c.ops[23].Add(1)
	return c.RawFileSystem.Lseek(x, i, o)
}
func (c *countFS) CopyFileRange(x <-chan struct{}, i *fuse.CopyFileRangeIn) (uint32, fuse.Status) {
	c.ops[24].Add(1)
	return c.RawFileSystem.CopyFileRange(x, i)
}
func (c *countFS) Fallocate(x <-chan struct{}, i *fuse.FallocateIn) fuse.Status {
	c.ops[25].Add(1)
	return c.RawFileSystem.Fallocate(x, i)
}
func (c *countFS) Statx(x <-chan struct{}, i *fuse.StatxIn, o *fuse.StatxOut) fuse.Status {
	c.ops[26].Add(1)
	return c.RawFileSystem.Statx(x, i, o)
}
func (c *countFS) Read(x <-chan struct{}, i *fuse.ReadIn, buf []byte) (fuse.ReadResult, fuse.Status) {
	c.ops[27].Add(1)
	c.rdB.Add(int64(i.Size))
	return c.RawFileSystem.Read(x, i, buf)
}
func (c *countFS) Write(x <-chan struct{}, i *fuse.WriteIn, d []byte) (uint32, fuse.Status) {
	c.ops[28].Add(1)
	c.wrB.Add(int64(len(d)))
	return c.RawFileSystem.Write(x, i, d)
}
func (c *countFS) Writev(x <-chan struct{}, i *fuse.WriteIn, d [][]byte) (uint32, fuse.Status) {
	c.ops[len(opNames)-1].Add(1)
	for _, b := range d {
		c.wrB.Add(int64(len(b)))
	}
	return c.RawFileSystem.Writev(x, i, d)
}
func (c *countFS) Release(x <-chan struct{}, i *fuse.ReleaseIn) {
	c.ops[29].Add(1)
	c.RawFileSystem.Release(x, i)
}
func (c *countFS) ReleaseDir(i *fuse.ReleaseIn) {
	c.ops[30].Add(1)
	c.RawFileSystem.ReleaseDir(i)
}
func (c *countFS) Forget(id, n uint64) {
	c.ops[31].Add(1)
	c.RawFileSystem.Forget(id, n)
}

func (c *countFS) dump(path string) error {
	ops := map[string]int64{}
	var total int64
	for i, n := range opNames {
		if v := c.ops[i].Load(); v != 0 {
			ops[n] = v
			total += v
		}
	}
	var ru syscall.Rusage
	syscall.Getrusage(syscall.RUSAGE_SELF, &ru)
	st := map[string]any{
		"ops": ops, "ops_total": total,
		"daemon_read_bytes": c.rdB.Load(), "daemon_write_bytes": c.wrB.Load(),
		"daemon_utime_s": float64(ru.Utime.Nano()) / 1e9,
		"daemon_stime_s": float64(ru.Stime.Nano()) / 1e9,
	}
	if c.blobs != nil {
		st["fetches"] = c.blobs.fetches.Load()
		st["fetched_bytes"] = c.blobs.fetchedBytes.Load()
		st["fetch_wait_s"] = float64(c.blobs.fetchNs.Load()) / 1e9
		st["cache_hits"] = c.blobs.cacheHits.Load()
	}
	b, _ := json.Marshal(st)
	if err := os.WriteFile(path+".tmp", b, 0o644); err != nil {
		return err
	}
	return os.Rename(path+".tmp", path)
}
